// Checks the synthetic test ROM in tests/data/test48.rom, the host firmware the
// conformance suites in tests/data/z80test run on. The real Spectrum ROM cannot
// be committed, so the emulator's core tests would otherwise have no boot ROM at
// all; this one is generated by tools/make_test_rom.py and contains no
// copyrighted code.
//
// The ROM is also a useful probe of the machine itself: it only uses features
// the suites need, so a failure here means the CPU, the ULA port, the interrupt
// path or the RAM banking is broken, not the suite.

#include <string>
#include <vector>

#include "test_framework.h"

#include "core/machine.h"

using rainbow::Machine;
using rainbow::MachineType;
using rainbow::u16;
using rainbow::u8;

namespace {

// The ROM's own symbols, mirrored from tools/make_test_rom.py.
constexpr u16 kPrintChar = 0x0132;
constexpr u16 kIdle = 0x0123;
constexpr u16 kGlyphBase = 0x3D00;
constexpr u16 kCursorRow = 0x5B00;
constexpr u16 kCursorCol = 0x5B01;
constexpr u16 kKeyRow6 = 0x5B02;
constexpr u16 kFrameCount = 0x5B04;

// Pixel address of a character cell, using the Spectrum's interleaved layout.
u16 cellBase(int row, int column) {
  const int y = row * 8;
  return u16(0x4000 + ((y & 0xC0) << 5) + ((y & 0x07) << 8) + ((y & 0x38) << 2) + column);
}

u8 glyphByte(Machine& machine, int ch, int line) {
  return machine.memRead(u16(kGlyphBase + (ch - 32) * 8 + line), 0);
}

bool cellShows(Machine& machine, int row, int column, int ch) {
  const u16 base = cellBase(row, column);
  for (int line = 0; line < 8; ++line) {
    if (machine.memRead(u16(base + (line << 8)), 0) != glyphByte(machine, ch, line)) return false;
  }
  return true;
}

std::string readRow(Machine& machine, int row) {
  std::string text;
  for (int column = 0; column < 32; ++column) {
    const u16 base = cellBase(row, column);
    char found = ' ';
    for (int ch = 32; ch < 128; ++ch) {
      bool same = true;
      for (int line = 0; line < 8 && same; ++line) {
        if (machine.memRead(u16(base + (line << 8)), 0) != glyphByte(machine, ch, line)) same = false;
      }
      if (same) {
        found = char(ch);
        break;
      }
    }
    text += found;
  }
  while (!text.empty() && text.back() == ' ') text.pop_back();
  return text;
}

} // namespace

TEST(test_rom_is_loadable_and_boots) {
  Machine machine(MachineType::Spectrum48);
  CHECK(machine.loadRom(RAINBOW_SOURCE_DIR "/tests/data/test48.rom"));
  CHECK_EQ(machine.romBank(), 0);

  for (int frame = 0; frame < 8; ++frame) machine.runFrame();

  // The banner is the first thing the ROM prints, so it proves the boot code,
  // the glyph renderer and the Spectrum screen layout all agree.
  const std::string first = readRow(machine, 0);
  CHECK(first == "RainbowNext test ROM");
  CHECK(readRow(machine, 1) == "no copyrighted code");
}

TEST(test_rom_prints_through_rst_10) {
  Machine machine(MachineType::Spectrum48);
  CHECK(machine.loadRom(RAINBOW_SOURCE_DIR "/tests/data/test48.rom"));
  for (int frame = 0; frame < 8; ++frame) machine.runFrame();

  // Park the CPU on the idle loop, then call the ROM's print routine with a
  // known character and let it return to the idle loop.
  auto& registers = machine.cpu().regs();
  machine.memWrite(0x7FF0, u8(kIdle & 0xFF), 0);
  machine.memWrite(0x7FF1, u8(kIdle >> 8), 0);
  registers.sp = 0x7FF0;
  registers.a = 'Q';
  registers.pc = kPrintChar;
  registers.halted = false;

  for (int i = 0; i < 2000; ++i) machine.stepInstruction();

  // print_char advances the cursor, so the character lands one cell before it.
  const u8 row = machine.memRead(kCursorRow, 0);
  const u8 column = machine.memRead(kCursorCol, 0);
  CHECK(column > 0);
  CHECK(cellShows(machine, row, column - 1, 'Q'));
}

TEST(test_rom_reports_the_frame_counter) {
  Machine machine(MachineType::Spectrum48);
  CHECK(machine.loadRom(RAINBOW_SOURCE_DIR "/tests/data/test48.rom"));

  // The idle loop halts with interrupts enabled and the IM 1 handler bumps the
  // frame counter, so the counter is a direct check of the interrupt path.
  for (int frame = 0; frame < 4; ++frame) machine.runFrame();
  const u8 before = machine.memRead(kFrameCount, 0);
  for (int frame = 0; frame < 30; ++frame) machine.runFrame();
  const u8 after = machine.memRead(kFrameCount, 0);

  CHECK(after != before);
  CHECK_EQ(int(u8(after - before)), 30);
}

TEST(test_rom_reads_the_keyboard) {
  Machine machine(MachineType::Spectrum48);
  CHECK(machine.loadRom(RAINBOW_SOURCE_DIR "/tests/data/test48.rom"));
  for (int frame = 0; frame < 8; ++frame) machine.runFrame();

  // Row 6 with no key down reads 0x1F: the ROM masks off the border, EAR and
  // unused bits so only the five key columns survive.
  CHECK_EQ(int(machine.memRead(kKeyRow6, 0)), 0x1F);

  machine.keyboard().setKey(6, 0, true); // ENTER
  for (int frame = 0; frame < 4; ++frame) machine.runFrame();
  CHECK_EQ(int(machine.memRead(kKeyRow6, 0)), 0x1E);

  machine.keyboard().setKey(6, 0, false);
  for (int frame = 0; frame < 4; ++frame) machine.runFrame();
  CHECK_EQ(int(machine.memRead(kKeyRow6, 0)), 0x1F);
}

TEST(test_rom_ships_a_full_glyph_table) {
  Machine machine(MachineType::Spectrum48);
  CHECK(machine.loadRom(RAINBOW_SOURCE_DIR "/tests/data/test48.rom"));

  // The test harnesses read the screen back by matching cells against this
  // table, so the glyphs must be distinct for the matching to be unambiguous.
  std::vector<std::string> shapes;
  for (int ch = 32; ch < 128; ++ch) {
    std::string shape;
    for (int line = 0; line < 8; ++line) shape += char(glyphByte(machine, ch, line));
    for (const std::string& other : shapes) CHECK(shape != other);
    shapes.push_back(shape);
  }
  CHECK_EQ(int(shapes.size()), 96);
}

TEST(test_rom_idle_port_read_is_bf) {
  Machine machine(MachineType::Spectrum48);
  CHECK(machine.loadRom(RAINBOW_SOURCE_DIR "/tests/data/test48.rom"));

  // With no key pressed and no tape running, port 0xFE reads 0xBF: bits 0-4
  // high, bit 5 high, the EAR bit low and bit 7 high. The Z80 conformance
  // suites read this port before every IN test and report a failure when it
  // differs, so the whole `IN` group depends on it.
  CHECK_EQ(int(machine.ioRead(0xFE, 0)), 0xBF);
  machine.keyboard().setKey(6, 0, true);
  CHECK_EQ(int(machine.ioRead(0xFE, 0)), 0xBE);
}

TEST(test_rom_reboots_into_the_banner) {
  Machine machine(MachineType::Spectrum48);
  CHECK(machine.loadRom(RAINBOW_SOURCE_DIR "/tests/data/test48.rom"));
  for (int frame = 0; frame < 8; ++frame) machine.runFrame();
  CHECK(readRow(machine, 0) == "RainbowNext test ROM");

  // A reset must put the CPU back at 0x0000 with a clean cursor, so the banner
  // is printed once more instead of scrolling the old one away.
  machine.reset();
  for (int frame = 0; frame < 8; ++frame) machine.runFrame();
  CHECK(readRow(machine, 0) == "RainbowNext test ROM");
  CHECK_EQ(int(machine.memRead(kCursorRow, 0)), 3);
}
